+    () => run(callSource.token, observe),
+    zoneValues: {yieldTokenZoneKey: yieldSource.token},
+  ); // A zombie that fails AFTER abandonment must never surface as an
+  // unhandled zone error.
+  unawaited(inner.catchError((Object _) => ToolExecutionResult.text('')));
+
