          contains(StuckFollowUpAction.backgroundConvert),
        );
        expect(outcome.resultText, contains('sh-9-x'));
        expect(outcome.resultText, contains('/work/.fah/bash_jobs/sh-9-x.log'));
        expect(outcome.resultText, contains('[stuck-call]'));
        expect(
