    this.floor = const Duration(seconds: defaultStuckFloorSeconds),
    this.declaredTimeoutFactor = defaultStuckDeclaredTimeoutFactor,
    this.heartbeatInterval = const Duration(
      seconds: defaultStuckHeartbeatSeconds,
