      final replRecords = await livenessRecords(replEnv);
      expect(
        [for (final r in replRecords) normalized(r)],
        [for (final r in headlessRecords) normalized(r)],
        reason:
            'AC5: headless and the TUI produce the same session records '
            '(timing aside)',
      );
    },
  );
}

