    }
    int seconds(String key, int fallback) {
      final value = node[key];
      if (value == null) return fallback;
      if (value is! int) {
        throw ConfigException('"agent.stuckTool.$key" must be an integer');
      }
      if (value < 0) {
        throw ConfigException('"agent.stuckTool.$key" must be >= 0');
      }
      return value;
    }

